   for($i=1;$i<=5;$i++){ $v=(float)($_POST['discount'][$i]??0); if($v<0||$v>100) throw new RuntimeException('Discount must be between 0 and 100%.'); $db->prepare('UPDATE reseller_level_discounts SET discount_percent=? WHERE level=?')->execute([$v,$i]); }
   $msg='Level discounts saved.';
