    if($code==='USDT_BEP20'){$config['receiving_address']=trim((string)($_POST['usdt_receiving_address']??''));$config['rpc_url']=trim((string)($_POST['usdt_rpc_url']??'https://bsc-dataseed.bnbchain.org'));$config['chain_id']=56;$config['token_contract']=trim((string)($_POST['usdt_token_contract']??'0x55d398326f99059ff775485246999027b3197955'));$config['decimals']=18;$config['min_confirmations']=max(1,(int)($_POST['usdt_min_confirmations']??12));}
    $s=$db->prepare('UPDATE payment_methods SET name=?,enabled=?,min_deposit=?,instructions=?,sort_order=?,config_json=? WHERE code=?');$s->execute([$name,$enabled,$min,$instructions,$sort,json_encode($config,JSON_UNESCAPED_SLASHES),$code]);
   }
   $msg='Payment settings saved.';
  }
  if($action==='telegram'){$lt=trim((string)($_POST['license_bot_token']??''));$lc=trim((string)($_POST['license_admin_chat_id']??''));if($lt===''||$lc==='') throw new RuntimeException('License Control Bot token and admin chat ID are required.');$dt=trim((string)($_POST['deposit_bot_token']??''));$dc=trim((string)($_POST['deposit_admin_chat_id']??''));$s=$db->prepare('INSERT INTO telegram_settings(id,bot_token,admin_chat_id,license_bot_token,license_admin_chat_id,deposit_bot_token,deposit_admin_chat_id) VALUES(1,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE bot_token=VALUES(bot_token),admin_chat_id=VALUES(admin_chat_id),license_bot_token=VALUES(license_bot_token),license_admin_chat_id=VALUES(license_admin_chat_id),deposit_bot_token=VALUES(deposit_bot_token),deposit_admin_chat_id=VALUES(deposit_admin_chat_id)');$s->execute([$lt,$lc,$lt,$lc,$dt?:null,$dc?:null]);$msg='Telegram settings saved.';}
 }
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();error_log('SkyNoc settings error: '.$e->getMessage());}
